-- Wichita and El Dorado: five active rows over the area
UPDATE "City" SET "published" = 1, "intro" = 'Wichita has an open play night, a shop that hosts beginner classes and a teacher whose lessons are booked online. Green Table Club runs a Mahj Monday open play that its page calls American Mahjong, Fenway Goods & Gifts at Bradley Fair hosts a ticketed beginner class that includes a National Mah Jongg League card, and Mod Mahj sells a first lesson covering the tiles, the card and how to deal. Nearby, Bradford Memorial Library in El Dorado hosts public mahjong events. If you are new, start with the beginner class at Fenway Goods & Gifts.', "updatedAt" = CURRENT_TIMESTAMP WHERE "slug" = 'wichita';
